sources.src/ClipboardReader.ets:
export class ClipboardReader {
  readContent(): string {
    return pasteboard.getSystemPasteboard().getData().getPrimaryText()
  }
}

sources.src/PaletteConverter.ets:
export class PaletteConverter {
  convertValue(value: string): number {
    return Number.parseInt(value, 16)
  }
}

